import request from '@/utils/request'
/**
 *
 * 员工管理
 *
 **/
// 登录、
export const login = (data: any) =>
  request({
    'url': '/employee/login',
    'method': 'post',
    data
  })
  // 退出
 export const userLogout = (params: any) =>
 request({
   'url': `/employee/logout`, // 授课老师接口
   'method': 'post',
   params
 })

export const getEmployeeList = (params: any) => {
  return request({
    url: '/employee/page',
    method: 'get',
    params
  })
}

// 修改---启用禁用接口
export const enableOrDisableEmployee = (params: any) => {
  return request({
    url: `/employee/status/${params.status}`,
    method: 'post',
    params: { id:params.id }
  })
}

// 新增---添加员工
export const addEmployee = (params: any) => {
  return request({
    url: '/employee',
    method: 'post',
    data: { ...params }
  })
}

// 修改---添加员工
export const editEmployee = (params: any) => {
  return request({
    url: '/employee',
    method: 'put',
    data: { ...params }
  })
}

// 修改页面反查详情接口
export const queryEmployeeById = (id: string | (string | null)[]) => {
  return request({
    url: `/employee/${id}`,
    method: 'get'
  })
}

// 修改密码接口
export const editPassword = (data: { empId: number | string; oldPassword: string; newPassword: string }) => {
  return request({
    url: '/employee/editPassword',
    method: 'put',
    data
  })
}

// ===== 权限管理相关接口 =====

// 获取所有权限等级选项（用于下拉框）
export const getRoleLevelOptions = () => {
  return request({
    url: '/employee/roleLevels',
    method: 'get'
  })
}

// 获取员工权限信息
export const getEmployeeRoleInfo = (employeeId: number | string) => {
  return request({
    url: `/employee/role/${employeeId}`,
    method: 'get'
  })
}

// 提升员工权限（仅SUPER可用）
export const upgradeEmployeeRole = (data: { employeeId: number; newRole: number }) => {
  return request({
    url: '/employee/upgradeRole',
    method: 'post',
    data
  })
}
