import axios, { AxiosAdapter } from 'axios'
import { Message, MessageBox } from 'element-ui'
import { UserModule } from '@/store/modules/user'
import {
  getRequestKey,
  pending,
  checkPending,
  removePending
} from './requestOptimize'
import router from '@/router'
const CancelToken = axios.CancelToken;

// 403错误消息防抖：同一消息3秒内只显示一次
let lastPermissionError = '';
let lastPermissionErrorTime = 0;
const PERMISSION_ERROR_DEBOUNCE = 3000; // 3秒

const showPermissionError = (msg: string) => {
  const now = Date.now();
  if (msg === lastPermissionError && now - lastPermissionErrorTime < PERMISSION_ERROR_DEBOUNCE) {
    return; // 重复消息，跳过
  }
  lastPermissionError = msg;
  lastPermissionErrorTime = now;
  Message.error(msg);
};

const service = axios.create({
  baseURL: process.env.VUE_APP_BASE_API,
  'timeout': 600000
})

// Request interceptors
service.interceptors.request.use(
  (config: any) => {
    // console.log(config, 'config')
    // config.data = config.params
    // Add X-Access-Token header to every request, you can add other custom headers here
    if (UserModule.token) {
      config.headers['token'] = UserModule.token
    } else if (UserModule.token && config.url != '/login') {
      window.location.href = '/login'
      return false
    }

    // config.headers['Access-Control-Allow-Origin'] = '*'
    // config.headers['Content-Type'] = 'application/json;'
    // get请求映射params参数
    if (config.method === 'get' && config.params) {
      let url = config.url + '?';
      for (const propName of Object.keys(config.params)) {
        const value = config.params[propName];
        var part = encodeURIComponent(propName) + '=';
        if (value !== null && typeof (value) !== 'undefined') {
          if (typeof value === 'object') {
            for (const key of Object.keys(value)) {
              let params = propName + '[' + key + ']';
              var subPart = encodeURIComponent(params) + '=';
              url += subPart + encodeURIComponent(value[key]) + '&';
            }
          } else {
            url += part + encodeURIComponent(value) + '&';
          }
        }
      }
      url = url.slice(0, -1);
      config.params = {};
      config.url = url;
    }
    // 计算当前请求key值
    const key = getRequestKey(config);
    // console.log(pending,key,checkPending(key),'checkPending(key)')
    if (checkPending(key)) {
      // 重复请求则取消当前请求
      const source = CancelToken.source();
      config.cancelToken = source.token;
      source.cancel('重复请求');
    } else {
      // 加入请求字典
      pending[key] = true;
    }
    return config
  },
  (error: any) => {
    Promise.reject(error)
  }
)

// Response interceptors
service.interceptors.response.use(
  (response: any) => {
    // console.log(response, 'response')
    if (response.data.status === 401) {
      router.push('/login')
      // const res = response.data
      // return response
    }
    // 请求完成，先删除请求中状态（必须在修改 URL 之前，否则 key 不匹配）
    const key = getRequestKey(response.config);
    removePending(key);
    //请求响应中的config的url会带上代理的api需要去掉
    response.config.url = response.config.url.replace('/api', '')
    // if (response.data.code === 0) {
    //   Message.error(response.data.msg)
    //   // if(response.data.msg === 'NOTLOGIN' || response.data.msg === '未登录'){
    //   //   router.push('/login')
    //   // }
    //   // return window.location.href = '/login'
    //   // window.location.href = '/login'
    //   // return false
    // } else
    if (response.data.code === 1) {
      // const res = response.data
      return response
    }
    return response
  },
  (error: any) => {
    // console.log(error.config, pending, 'error')
    // 请求完成，先删除请求中状态（必须在修改 URL 之前，否则 key 不匹配）
    if (error.config) {
      const key = getRequestKey(error.config);
      removePending(key);
      //请求响应中的config的url会带上代理的api需要去掉
      error.config.url = error.config.url.replace('/api', '')
    }
    if (error && error.response) {
      // 优先从响应体获取后端返回的错误消息
      const backendMsg = error.response.data && error.response.data.msg ? error.response.data.msg : null;
      
      switch (error.response.status) {
        case 401:
          // 显示后端返回的具体消息，如果没有则使用默认消息
          if (backendMsg) {
            Message.error(backendMsg);
          }
          router.push('/login');
          break;
        case 403:
          // 显示后端返回的权限错误消息，使用防抖机制避免重复提示
          showPermissionError(backendMsg || '权限不足');
          // 创建带标记的错误，让组件层知道已经显示过消息
          const permissionError = new Error(backendMsg || '权限不足');
          (permissionError as any).handled = true; // 标记为已处理
          return Promise.reject(permissionError);
        case 405:
          error.message = '请求错误';
          break;
        default:
          // 其他错误也尝试显示后端消息
          if (backendMsg) {
            Message.error(backendMsg);
            return Promise.reject(new Error(backendMsg));
          }
      }
    }
    // console.log(error, pending, 'error11')
    // Message({
    //   'message': error.message,
    //   'type': 'error',
    //   'duration': 5 * 1000
    // })
    // router.push('/login')
    return Promise.reject(error)
  }
)

/**
 * 处理catch块中的错误，避免重复显示已处理的错误
 * @param err 错误对象
 * @param prefix 错误消息前缀，默认为"请求出错了"
 */
export const handleCatchError = (err: any, prefix: string = '请求出错了') => {
  // 如果错误已经在拦截器中处理过（如403），不再重复显示
  if (err && err.handled) {
    return;
  }
  Message.error(`${prefix}：${err.message || err}`);
};

export default service
