import router from './router'
import NProgress from 'nprogress'
import 'nprogress/nprogress.css'
import { Message } from 'element-ui'
import { Route } from 'vue-router'
import { UserModule } from '@/store/modules/user'
import Cookies from 'js-cookie'
import { getNeedChangePassword } from '@/utils/cookies'

NProgress.configure({ 'showSpinner': false })

router.beforeEach(async (to: Route, _: Route, next: any) => {
  NProgress.start()
  if (Cookies.get('token')) {
    // 同步本地存储的 needChangePassword 状态到 store
    // 这样页面刷新后也能正确显示弹窗
    const needChange = getNeedChangePassword() === 'true'
    if (needChange && !UserModule.needChangePassword) {
      // 需要通过 mutation 更新，但这里我们直接依赖 store 初始化时的读取
      // store 初始化时已经从 cookie 读取了状态
    }
    next()
  } else {
    if (!to.meta.notNeedAuth) {
      next('/login')
    } else {
      next()
    }
  }
})

router.afterEach((to: Route) => {
  NProgress.done()
  document.title = to.meta.title
})
