




















import { Component, Watch } from 'vue-property-decorator'
import { mixins } from 'vue-class-component'
import { DeviceType, AppModule } from '@/store/modules/app'
import { UserModule } from '@/store/modules/user'
import { AppMain, Navbar, Sidebar } from './components'
import ResizeMixin from './mixin/resize'
import ChangePasswordModal from '@/components/ChangePasswordModal/index.vue'

@Component({
  name: 'Layout',
  components: {
    AppMain,
    Navbar,
    Sidebar,
    ChangePasswordModal,
  },
})
export default class extends mixins(ResizeMixin) {
  private showChangePasswordModal = false

  get classObj() {
    return {
      hideSidebar: !this.sidebar.opened,
      openSidebar: this.sidebar.opened,
      withoutAnimation: this.sidebar.withoutAnimation,
      mobile: this.device === DeviceType.Mobile,
    }
  }

  // 监听 needChangePassword 状态
  get needChangePassword() {
    return UserModule.needChangePassword
  }

  @Watch('needChangePassword', { immediate: true })
  onNeedChangePasswordChange(val: boolean) {
    this.showChangePasswordModal = val
  }

  created() {
    // 初始化时检查是否需要强制修改密码
    this.checkNeedChangePassword()
  }

  private checkNeedChangePassword() {
    if (UserModule.needChangePassword) {
      this.showChangePasswordModal = true
    }
  }

  private onPasswordChangeSuccess() {
    this.showChangePasswordModal = false
    this.$message.success('密码已修改，现在可以正常使用系统')
  }

  private handleClickOutside() {
    AppModule.CloseSideBar(false)
  }
}
